        print(f"  Number of edges: {len(shape.Edges)}")

        for i, face in enumerate(shape.Faces):
            print(f"    Face {i}: {face.Surface.Type}")
            if hasattr(face.Surface, 'Surface'):
                surf = face.Surface.Surface
                print(f"      Surface type: {type(surf).__name__}")
                if hasattr(surf, 'Degree'):
                    print(f"      BSpline degree: {surf.Degree}")

        for i, edge in enumerate(shape.Edges):
            curve = edge.Curve
            print(f"    Edge {i}: {curve.__class__.__name__}")
            if hasattr(curve, 'Degree'):
                print(f"      BSpline degree: {curve.Degree}")
            if hasattr(curve, 'NbPoles'):
                print(f"      Number of poles: {curve.NbPoles}")

# Recompute to ensure no errors
print("\n=== Recomputing document ===")
try:
    doc.recompute()
    print("Recompute successful - no errors!")
except Exception as e:
    print(f"Recompute error: {e}")

FreeCAD.closeDocument(doc.Name)
print("\n=== Verification Complete ===")
